B.cka=A.a(s(["obrigado","compra","confian\xe7a","venda"]),t.s)
B.bhH=new A.eI("agr-01",B.ms,"Agradecer pela compra","Muito obrigado pela sua compra e pela confian\xe7a no nosso trabalho!","Thank you so much for your purchase and for trusting our work!","\xa1Muchas gracias por tu compra y por confiar en nuestro trabajo!",B.cka)
B.cj5=A.a(s(["avalia\xe7\xe3o","elogio","carinho","equipe"]),t.s)
B.bij=new A.eI("agr-02",B.ms,"Agradecer por avalia\xe7\xe3o positiva","Que alegria ler sua avalia\xe7\xe3o! Muito obrigado pelo carinho, isso motiva muito toda a nossa equipe.","What a joy to read your review! Thank you so much for your kind words, it truly motivates our whole team.","\xa1Qu\xe9 alegr\xeda leer tu rese\xf1a! Muchas gracias por tus palabras, motivan much\xedsimo a todo nuestro equipo.",B.cj5)
B.cfB=A.a(s(["paci\xeancia","compreens\xe3o","espera"]),t.s)
B.bhS=new A.eI("agr-03",B.ms,"Agradecer pela paci\xeancia","Muito obrigado pela sua paci\xeancia e compreens\xe3o enquanto resolv\xedamos tudo para voc\xea.","Thank you very much for your patience and understanding while we sorted everything out for you.","Muchas gracias por tu paciencia y comprensi\xf3n mientras resolv\xedamos todo para ti.",B.cfB)
